    public static String get(String language,String key,Object...args){
        int locale="de".equals(language)?3:"es".equals(language)?4:"pt".equals(language)?5:"it".equals(language)?6:"en".equals(language)?2:1;
        for(String[] row:COPY)if(row[0].equals(key))return args.length==0?row[locale]:String.format(Locale.forLanguageTag(language),row[locale],args);
        throw new IllegalArgumentException("Unknown arcade string: "+key);
    }
    private Arcade121Strings(){}
